import {factKinds,safeWeb,combinedResume,projectChoices,applicationChecks,interviewPrep,textChanges} from './portfolio.js';
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};
export function mountPortfolio({getState,persist,onChange}){
 const $=s=>document.querySelector(s);let loaded=false;
 const button=el('button','Портфолио и источники','text-button');button.id='portfolio-open';button.type='button';$('#resume-profile-open').after(button);
 const dialog=el('dialog');dialog.id='portfolio-dialog';dialog.setAttribute('aria-labelledby','portfolio-title');
 dialog.innerHTML=`<div class="dialog-top"><h2 id="portfolio-title">Портфолио для CV</h2><button class="small-button" id="portfolio-close">Закрыть</button></div><div class="dialog-body"><p>Подтверди только то, что можешь объяснить на интервью. Новые факты не используются до подтверждения. Изменения не переписывают готовые черновики.</p><p id="portfolio-source-status" role="status"></p><form id="portfolio-links"><label class="resume-block">GitHub<input name="githubUrl" type="url" maxlength="2000"></label><label class="resume-block">LinkedIn<input name="linkedinUrl" type="url" maxlength="2000"></label><button class="secondary">Сохранить ссылки</button></form><p class="field-help">Ссылки не подключают аккаунты. Ниже — вымышленные примеры проектов. Скопируй нужный факт из профиля в форму ниже. Закрытые проекты и документы добавляй только если хочешь включать их в CV.</p><div id="portfolio-facts"></div><details><summary>Добавить факт из LinkedIn или другого источника</summary><form id="portfolio-add"><label class="resume-block">Тип<select name="kind">${Object.entries(factKinds).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label class="resume-block">Факт на английском — один проект, навык или блок опыта<textarea name="text" required maxlength="4000" rows="5"></textarea></label><label class="resume-block">Ссылка на источник<input name="source" type="url" maxlength="2000"></label><button class="secondary">Добавить на проверку</button></form></details><p id="portfolio-result" role="status"></p></div>`;
 document.body.append(dialog);$('#portfolio-close').onclick=()=>dialog.close();
 const data=()=>getState().portfolio||(getState().portfolio={facts:[]});
 function save(message){persist(message);onChange?.();$('#portfolio-result').textContent=message;}
 function render(){const p=data();for(const k of ['githubUrl','linkedinUrl'])$('#portfolio-links').elements[k].value=p[k]||'';$('#portfolio-source-status').textContent=p.linkedinStatus||'Сохрани ссылки и добавь свои факты.';const container=$('#portfolio-facts');container.replaceChildren();
  for(const fact of p.facts||[]){const card=el('section',undefined,'portfolio-card');card.append(el('strong',`${factKinds[fact.kind]||'Факт'} · ${fact.approved?'Подтверждён':'На проверке'}`));const label=el('label','Текст для CV','resume-block');const text=el('textarea');text.rows=4;text.maxLength=4000;text.value=fact.text;label.append(text);card.append(label);if(safeWeb(fact.source)){const a=el('a','Открыть источник');a.href=safeWeb(fact.source);a.target='_blank';a.rel='noopener noreferrer';card.append(a)}if(fact.note)card.append(el('p',fact.note,'field-help'));const controls=el('div',undefined,'resume-tools');const approve=el('button','Подтвердить и использовать','secondary'),exclude=el('button','Не использовать','small-button');approve.dataset.approveFact=fact.id;exclude.dataset.excludeFact=fact.id;approve.onclick=()=>{if(!text.value.trim())return;fact.text=text.value.trim();fact.approved=true;fact.approvedAt=new Date().toISOString();save('Факт подтверждён. Пересобери нужный черновик, чтобы применить.');render()};exclude.onclick=()=>{fact.text=text.value.trim();fact.approved=false;save('Факт исключён из будущих адаптаций.');render()};text.oninput=()=>{approve.textContent='Подтвердить изменённый текст';};controls.append(approve,exclude);card.append(controls);container.append(card);}
 }
 button.onclick=async()=>{dialog.showModal();$('#portfolio-result').textContent='';if(!getState().portfolio&&!loaded){try{const r=await fetch('/api/portfolio-baseline',{cache:'no-store'});if(!r.ok)throw Error();const response=await r.json();if(response.portfolio)getState().portfolio={...response.portfolio,facts:response.portfolio.facts.map(f=>({...f,approved:false}))};else getState().portfolio={facts:[]};loaded=true;persist();}catch{$('#portfolio-result').textContent='Не удалось загрузить предложения. Можно добавить факты вручную.'}}render()};
 $('#portfolio-links').onsubmit=e=>{e.preventDefault();const p=data();for(const k of ['githubUrl','linkedinUrl']){const v=e.currentTarget.elements[k].value.trim();if(v&&!safeWeb(v)){$('#portfolio-result').textContent='Нужна ссылка http или https.';return}}for(const k of ['githubUrl','linkedinUrl'])p[k]=safeWeb(e.currentTarget.elements[k].value);const profile=getState().profile;if(profile){profile.githubUrl=p.githubUrl;profile.linkedinUrl=p.linkedinUrl;}save('Ссылки сохранены в CV и профиле поиска.');};
 $('#portfolio-add').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;if(!f.elements.text.value.trim())return;const p=data();if(p.facts.length>=50){$('#portfolio-result').textContent='Достигнут лимит 50 фактов. Отредактируй существующие.';return}p.facts.push({id:'manual-'+Date.now()+'-'+Math.random().toString(36).slice(2),kind:f.elements.kind.value,text:f.elements.text.value.trim(),source:safeWeb(f.elements.source.value),approved:false,note:'Добавлено вручную; проверь содержание и личный вклад.'});save('Факт добавлен на проверку.');f.reset();render()};
 return{isOpen:()=>dialog.open,base:()=>combinedResume(getState().resumeProfile,getState().portfolio),choices:job=>projectChoices(combinedResume(getState().resumeProfile,getState().portfolio),job)};
}

export function mountApplicationTools({base,currentJob,currentDraft,regenerate,persist,getState,saveDraft}){
 const $=s=>document.querySelector(s);const box=el('div');box.id='application-tools';
 box.innerHTML=`<details open><summary>Почему выбраны эти проекты</summary><p class="field-help">Автоматически выбираются два наиболее близких проекта. Можно изменить выбор и пересобрать черновик.</p><div id="resume-project-choices"></div><button id="resume-project-apply" class="small-button">Применить выбор проектов</button><p id="resume-explanation"></p><details><summary>Изменения при последней сборке</summary><div id="resume-changes"></div></details></details><details><summary>Проверка перед откликом</summary><button id="resume-check" class="small-button">Проверить текущий текст</button><ul id="resume-checks"></ul></details><details><summary>Подготовиться к интервью · 35 минут</summary><p class="field-help">Вопросы для тренировки по требованиям, а не известные вопросы работодателя.</p><ol id="resume-questions"></ol><ul id="resume-prep-plan"></ul></details><details><summary>Черновик email</summary><label class="resume-block">Email работодателя<input id="resume-recipient" type="email" maxlength="320" placeholder="Адрес из вакансии"></label><p class="field-help">Проверь адрес по источнику. Почта не подключена; кнопка только открывает черновик в твоём почтовом приложении. PDF нужно прикрепить вручную.</p><button id="resume-email-open" class="secondary">Открыть черновик письма</button><p id="resume-email-result" role="status"></p></details>`;
 $('#resume-evidence').after(box);let choices=[];
 const nowDraft=()=>({...currentDraft(),cvText:$('#resume-cv-text').value,coverText:$('#resume-cover-text').value,subject:$('#resume-subject').value,reviewed:$('#resume-reviewed').checked});
 function checks(){const list=$('#resume-checks');list.replaceChildren();for(const item of applicationChecks(base(),currentJob(),nowDraft()))list.append(el('li',item.text,'check-'+item.level));}
 $('#resume-check').onclick=checks;
 $('#resume-project-apply').onclick=()=>{const selected=choices.filter((_,i)=>$('#project-choice-'+i).checked).map(p=>p.text);regenerate(selected)};
 $('#resume-recipient').onchange=e=>{const j=currentJob();if(j){j.applicationRecipient=e.target.value.trim();persist()}};
 $('#resume-email-open').onclick=()=>{const d=nowDraft(),input=$('#resume-recipient'),to=input.value.trim();if(!d.reviewed){$('#resume-email-result').textContent='Сначала проверь текст и поставь отметку подтверждения.';return}if(!to||!input.checkValidity()||/[\r\n]/.test(to)){$('#resume-email-result').textContent='Укажи корректный адрес работодателя из вакансии.';return}if(!saveDraft())return;const j=currentJob();j.applicationRecipient=to;persist();const a=el('a');a.href='mailto:'+encodeURIComponent(to)+'?subject='+encodeURIComponent(d.subject.replace(/[\r\n]/g,' '))+'&body='+encodeURIComponent(d.coverText);a.click();$('#resume-email-result').textContent='Запрошено открытие почтового приложения. Прикрепи PDF версии '+j.applicationDraft.version+' и проверь получателя. Отправка и статус отклика не изменены.';};
 return{render(j,d){choices=projectChoices(base(),j);const selected=d.selectedProjects||choices.slice(0,2).map(x=>x.text),container=$('#resume-project-choices');container.replaceChildren();choices.forEach((p,i)=>{const label=el('label',undefined,'project-choice');const input=el('input');input.type='checkbox';input.id='project-choice-'+i;input.checked=selected.includes(p.text);label.append(input,el('span',p.title+' — '+p.reason));container.append(label)});$('#resume-explanation').textContent='Выделены навыки: '+(d.matched?.join(', ')||'нет совпадений')+'. Проекты выбраны по стеку и направлению роли. Остальные факты сохранены в базе.';const changes=$('#resume-changes');changes.replaceChildren();if(d.changes){for(const [key,label]of [['added','Добавлено'],['removed','Убрано']]){changes.append(el('strong',label));const ul=el('ul');for(const line of d.changes[key]||[])ul.append(el('li',line));changes.append(ul)}}else changes.append(el('p','Это прежний черновик. Сравнение появится после пересборки.'));checks();const prep=interviewPrep(j,d);for(const [id,items]of [['resume-questions',prep.questions],['resume-prep-plan',prep.plan]]){$('#'+id).replaceChildren(...items.map(x=>el('li',x)))}$('#resume-recipient').value=j.applicationRecipient||(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(j.recruiter||'')?j.recruiter:'');$('#resume-email-result').textContent='';}};
}
